import { sequence, type Handle } from "@sveltejs/kit/hooks";
import { paraglideMiddleware } from "#lib/paraglide/server.js";
import { getTextDirection } from "#lib/paraglide/runtime.js";
import { applySecurityHeaders } from "#lib/security/headers.ts";

/**
 * Server-side hook sequence (see https://paraglidejs.com/sveltekit and the
 * SvelteKit hooks docs):
 *
 * 1. security-headers handle — applies the standard security baseline to
 *    every server response (the CSP itself is generated by SvelteKit from
 *    the `csp` configuration in vite.config.ts).
 * 2. Paraglide middleware — resolves the request locale and swaps the
 *    `%lang%` / `%dir%` placeholders in the served HTML template.
 */

// Documented residual: immutable `/_app/…` assets are served by the
// adapter-node static layer (file map decided at boot) OUTSIDE this hook
// chain — the security baseline is an HTML-delivery contract; the asset
// layer relies on the browser cache + immutable Content-type responses.
const securityHeadersHandle: Handle = async ({ event, resolve }) => {
  const response = await resolve(event);
  applySecurityHeaders(response);
  return response;
};

const paraglideHandle: Handle = ({ event, resolve }) =>
  paraglideMiddleware(event.request, ({ request: localizedRequest, locale }) => {
    return resolve(
      { ...event, request: localizedRequest },
      {
        transformPageChunk: ({ html }) => {
          return html.replace("%lang%", locale).replace("%dir%", getTextDirection(locale));
        },
      },
    );
  });

export const handle = sequence(securityHeadersHandle, paraglideHandle);
